-- Zimam core schema.
-- Timestamps are Unix milliseconds. Rows are soft-deleted (deleted_at) so sync can
-- tell clients about deletions. Ids are UUIDs generated by the client or the server.

CREATE TABLE users (
  id TEXT PRIMARY KEY,
  apple_sub TEXT NOT NULL UNIQUE,
  email TEXT,
  name TEXT,
  settings TEXT NOT NULL DEFAULT '{}',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);

CREATE TABLE sessions (
  token_hash TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  device TEXT,
  created_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL,
  last_used_at INTEGER NOT NULL
);
CREATE INDEX sessions_user ON sessions(user_id);

-- A project is a task list; a folder groups projects (parent_id).
CREATE TABLE projects (
  id TEXT PRIMARY KEY,
  owner_id TEXT NOT NULL REFERENCES users(id),
  parent_id TEXT,
  kind TEXT NOT NULL DEFAULT 'project' CHECK (kind IN ('project', 'folder')),
  name TEXT NOT NULL,
  view TEXT NOT NULL DEFAULT 'list' CHECK (view IN ('list', 'kanban', 'calendar')),
  sort_order REAL NOT NULL DEFAULT 0,
  archived_at INTEGER,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  deleted_at INTEGER
);

CREATE TABLE project_members (
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role TEXT NOT NULL CHECK (role IN ('owner', 'editor', 'viewer')),
  added_at INTEGER NOT NULL,
  PRIMARY KEY (project_id, user_id)
);
CREATE INDEX project_members_user ON project_members(user_id);

-- Kanban columns of a project.
CREATE TABLE sections (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  name TEXT NOT NULL,
  sort_order REAL NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  deleted_at INTEGER
);
CREATE INDEX sections_project ON sections(project_id);

-- A task with project_id NULL lives in its owner's inbox and is private to them.
-- Due date is a local Gregorian date; Hijri is derived on the client (Umm al-Qura).
-- A task can instead be anchored to a prayer: due_prayer + due_prayer_offset minutes.
CREATE TABLE tasks (
  id TEXT PRIMARY KEY,
  owner_id TEXT NOT NULL REFERENCES users(id),
  project_id TEXT,
  section_id TEXT,
  parent_id TEXT,
  title TEXT NOT NULL,
  notes TEXT,
  status TEXT NOT NULL DEFAULT 'todo' CHECK (status IN ('todo', 'doing', 'done')),
  priority INTEGER NOT NULL DEFAULT 0 CHECK (priority BETWEEN 0 AND 3),
  tags TEXT NOT NULL DEFAULT '[]',
  due_date TEXT,
  due_time TEXT,
  due_prayer TEXT CHECK (due_prayer IN ('fajr', 'dhuhr', 'asr', 'maghrib', 'isha')),
  due_prayer_offset INTEGER,
  recurrence TEXT,
  assignee_id TEXT,
  sort_order REAL NOT NULL DEFAULT 0,
  completed_at INTEGER,
  search_text TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  deleted_at INTEGER
);
CREATE INDEX tasks_owner ON tasks(owner_id) WHERE project_id IS NULL;
CREATE INDEX tasks_project ON tasks(project_id);
CREATE INDEX tasks_parent ON tasks(parent_id);
CREATE INDEX tasks_due ON tasks(due_date);

-- Reminders are personal: each member of a shared project sets their own.
CREATE TABLE reminders (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id),
  task_id TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('time', 'prayer', 'location')),
  at TEXT,
  prayer TEXT CHECK (prayer IN ('fajr', 'dhuhr', 'asr', 'maghrib', 'isha')),
  offset_minutes INTEGER,
  location TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  deleted_at INTEGER
);
CREATE INDEX reminders_task ON reminders(task_id);

CREATE TABLE comments (
  id TEXT PRIMARY KEY,
  task_id TEXT NOT NULL,
  author_id TEXT NOT NULL REFERENCES users(id),
  body TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  deleted_at INTEGER
);
CREATE INDEX comments_task ON comments(task_id);

-- Change log that drives sync. Each row names the audience of the change:
-- a project (all its members) or a single user (inbox tasks, reminders).
CREATE TABLE changes (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  entity TEXT NOT NULL,
  entity_id TEXT NOT NULL,
  project_id TEXT,
  user_id TEXT,
  at INTEGER NOT NULL
);
CREATE INDEX changes_project ON changes(project_id, seq);
CREATE INDEX changes_user ON changes(user_id, seq);

-- Links to records in other services, for import now and two-way sync later.
CREATE TABLE external_refs (
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  source TEXT NOT NULL,
  external_id TEXT NOT NULL,
  entity TEXT NOT NULL,
  entity_id TEXT NOT NULL,
  synced_at INTEGER NOT NULL,
  PRIMARY KEY (user_id, source, external_id)
);
CREATE INDEX external_refs_entity ON external_refs(entity, entity_id);
